INSERT INTO `products` VALUES (128, '节能洗衣机', 1999, '家电', '节能洗衣机，采用变频技术，能耗低，洗涤效果好，静音设计，为您的家庭节省电费。有多种洗涤模式可选，适合不同衣物的洗涤需求。', 'https://img.freepik.com/free-photo/energy-saving-washing-machine_23-2148876016.jpg', 145, 4.6, '2026-04-08 19:09:39');
