INSERT INTO `products` VALUES (130, '环保水杯', 49.9, '日用品', '环保水杯，采用不锈钢或玻璃制成，可重复使用，减少一次性水杯的使用，为环保贡献一份力量。保温效果好，适合日常使用和外出携带。', 'https://img.freepik.com/free-photo/eco-friendly-water-bottle_23-2148876018.jpg', 267, 4.7, '2026-04-08 19:09:39');
INSERT INTO `products` VALUES (131, '有机坚果礼盒', 168, '食品', '有机坚果礼盒，采用有机种植，无农药无化肥，营养丰富，口感美味，是送礼的绝佳选择。包含核桃、杏仁、腰果、开心果等多种坚果，采用精美包装。', 'https://img.freepik.com/free-photo/organic-nuts-gift-box_23-2148876019.jpg', 156, 4.6, '2026-04-08 19:09:39');
INSERT INTO `products` VALUES (132, '可降解垃圾袋', 49.9, '家居用品', '可降解垃圾袋，采用环保材料制成，使用后可自然降解，不会对环境造成污染，是家庭垃圾分类的好帮手。韧性强，不易破损，适合各种垃圾的收纳。', 'https://img.freepik.com/free-photo/biodegradable-trash-bags_23-2148875999.jpg', 345, 4.4, '2026-04-08 19:09:39');
INSERT INTO `products` VALUES (133, '节能灯泡', 19.9, '家电', '节能灯泡，采用LED技术，能耗低，使用寿命长，比传统灯泡节能80%以上，为您的家庭节省电费。光线柔和，无频闪，保护眼睛健康。', 'https://img.freepik.com/free-photo/energy-saving-led-light-bulbs_23-2148875990.jpg', 523, 4.7, '2026-04-08 19:09:39');
