INSERT INTO `products` VALUES (148, '天然沐浴露', 59.9, '美妆', '天然沐浴露，采用天然成分制成，不含化学添加剂，温和清洁，滋润肌肤，适合各种肤质。有多种香型可选，如薰衣草、玫瑰、柠檬等。', 'https://img.freepik.com/free-photo/natural-shower-gel_23-2148876033.jpg', 234, 4.5, '2026-04-08 19:09:39');
INSERT INTO `products` VALUES (149, '环保笔', 19.9, '日用品', '环保笔，采用可回收材料制成，可重复使用，减少一次性笔的使用，为环保贡献一份力量。书写流畅，手感舒适，适合日常使用。', 'https://img.freepik.com/free-photo/eco-friendly-pens_23-2148876034.jpg', 456, 4.6, '2026-04-08 19:09:39');
INSERT INTO `products` VALUES (150, '有机大米', 69.9, '食品', '有机大米，采用有机种植，无农药无化肥，口感香糯，营养丰富，适合家庭日常食用。富含多种营养成分，对健康有益。', 'https://img.freepik.com/free-photo/organic-rice_23-2148876035.jpg', 178, 4.7, '2026-04-08 19:09:39');
