INSERT INTO `products` VALUES (152, '有机蔬菜种子', 19.9, '食品', '有机蔬菜种子，采用有机认证，无转基因，发芽率高，适合家庭阳台、庭院种植。包含多种蔬菜种子，如西红柿、黄瓜、辣椒等，满足家庭种植需求。', 'https://img.freepik.com/free-photo/organic-vegetable-seeds_23-2148876037.jpg', 123, 4.5, '2026-04-08 19:09:39');
