INSERT INTO `products` VALUES (194, '节能加湿器', 199, '家电', '节能加湿器，采用低功耗技术，能耗低，加湿效果好，为您的家庭提供舒适的湿度环境。有多种容量可选，适合不同面积的房间使用。', 'https://img.freepik.com/free-photo/energy-saving-humidifier_23-2148876072.jpg', 145, 4.6, '2026-04-08 19:09:39');
