INSERT INTO `products` VALUES (196, '环保鼠标垫', 29.9, '日用品', '环保鼠标垫，采用可回收材料制成，结实耐用，可重复使用，减少塑料鼠标垫的使用，为环保贡献一份力量。设计时尚美观，手感舒适，适合办公和游戏使用。', 'https://img.freepik.com/free-photo/eco-friendly-mouse-pad_23-2148876074.jpg', 234, 4.6, '2026-04-08 19:09:39');
INSERT INTO `products` VALUES (197, '有机芝麻', 39.9, '食品', '有机芝麻，采用有机种植，无农药无化肥，营养丰富，口感香美，适合烹饪和调味。富含多种营养成分，对健康有益。', 'https://img.freepik.com/free-photo/organic-sesame-seeds_23-2148876075.jpg', 198, 4.5, '2026-04-08 19:09:39');
INSERT INTO `products` VALUES (198, '可降解一次性餐纸', 29.9, '家居用品', '可降解一次性餐纸，采用环保材料制成，使用后可自然降解，不会对环境造成污染，适合家庭、餐厅等场合使用。柔软舒适，吸水性强，方便实用。', 'https://img.freepik.com/free-photo/biodegradable-dining-paper_23-2148876076.jpg', 345, 4.4, '2026-04-08 19:09:39');
INSERT INTO `products` VALUES (199, '节能空气净化器', 1299, '家电', '节能空气净化器，采用低功耗技术，能耗低，净化效果好，为您的家庭提供清新的空气环境。有多种功能可选，如除甲醛、除异味、除菌等，满足不同净化需求。', 'https://img.freepik.com/free-photo/energy-saving-air-purifier_23-2148876077.jpg', 123, 4.7, '2026-04-08 19:09:39');
INSERT INTO `products` VALUES (200, '测试商品1', 19.9, '食品', '测试商品1的描述', 'https://img.freepik.com/free-photo/fresh-organic-vegetables-in-a-box_1150-38087.jpg', 100, 4.5, '2026-04-08 19:48:50');
INSERT INTO `products` VALUES (201, '测试商品2', 29.9, '家居用品', '测试商品2的描述', 'https://img.freepik.com/free-photo/corn-starch-biodegradable-tableware-set_23-2148875989.jpg', 200, 4.6, '2026-04-08 19:48:50');
INSERT INTO `products` VALUES (202, '有机蔬菜礼盒', 128, '食品', '精选有机蔬菜，无农药无化肥，新鲜采摘，营养丰富，适合家庭日常食用。包含西红柿、黄瓜、茄子、青椒、西兰花等多种时令蔬菜，采用环保包装，确保新鲜度。', 'https://img.freepik.com/free-photo/fresh-organic-vegetables-in-a-box_1150-38087.jpg', 356, 4.8, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (203, '可降解餐具套装', 89.9, '家居用品', '采用玉米淀粉制成的可降解餐具，环保无污染，使用后可自然降解，不会对环境造成危害。包含碗、盘、杯子、叉子、勺子等多种餐具，适合家庭日常使用和户外野餐。', 'https://img.freepik.com/free-photo/corn-starch-biodegradable-tableware-set_23-2148875989.jpg', 289, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (204, '节能LED灯泡', 19.9, '家电', '节能LED灯泡，使用寿命长，能耗低，比传统灯泡节能80%以上，为您的家庭节省电费。采用优质材料制造，光线柔和，无频闪，保护眼睛健康。', 'https://img.freepik.com/free-photo/energy-saving-led-light-bulbs_23-2148875990.jpg', 523, 4.7, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (205, '有机棉T恤', 129, '服装', '采用有机棉制成的T恤，柔软舒适，透气性好，不含有害化学物质，对皮肤友好。设计简约时尚，适合日常穿着，有多种颜色可选。', 'https://img.freepik.com/free-photo/organic-cotton-t-shirt-hanging_23-2148875992.jpg', 187, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (206, '天然竹纤维毛巾', 39.9, '家居用品', '天然竹纤维毛巾，吸水性强，柔软舒适，抗菌防霉，使用寿命长，是家庭必备的绿色用品。采用天然竹纤维制成，不含化学添加剂，对皮肤友好。', 'https://img.freepik.com/free-photo/bamboo-fiber-towels-arrangement_23-2148875993.jpg', 412, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (207, '无添加洗发水', 89, '美妆', '无添加洗发水，不含硅油、parabens等有害成分，温和清洁，保护头皮健康，适合各种发质。采用天然植物提取成分，深层滋养头发，让头发更加柔顺亮泽。', 'https://img.freepik.com/free-photo/silicone-free-shampoo-bottle_23-2148875994.jpg', 234, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (208, '环保购物袋', 29.9, '日用品', '环保购物袋，采用可回收材料制成，结实耐用，可重复使用，减少塑料袋的使用，为环保贡献一份力量。设计时尚美观，容量大，适合日常购物使用。', 'https://img.freepik.com/free-photo/reusable-eco-shopping-bag_23-2148875995.jpg', 654, 4.7, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (209, '有机奶粉', 298, '母婴用品', '有机奶粉，采用有机奶源，无添加人工色素和防腐剂，营养丰富，适合婴幼儿饮用。含有丰富的蛋白质、钙、铁等营养成分，促进宝宝健康成长。', 'https://img.freepik.com/free-photo/organic-baby-formula-container_23-2148875996.jpg', 156, 4.9, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (210, '太阳能充电宝', 199, '数码产品', '太阳能充电宝，利用太阳能充电，环保节能，外出旅行必备，为您的电子设备提供持久电力。容量大，充电速度快，适合各种电子设备使用。', 'https://img.freepik.com/free-photo/solar-powered-portable-charger_23-2148875997.jpg', 278, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (211, '天然植物精油', 129, '美妆', '天然植物精油，采用纯植物提取，不含化学添加剂，具有舒缓、放松的功效，适合aromatherapy使用。有多种香型可选，如薰衣草、茶树、柠檬等，满足不同需求。', 'https://img.freepik.com/free-photo/natural-essential-oil-bottles_23-2148875998.jpg', 198, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (212, '可降解垃圾袋', 49.9, '家居用品', '可降解垃圾袋，采用环保材料制成，使用后可自然降解，不会对环境造成污染，是家庭垃圾分类的好帮手。韧性强，不易破损，适合各种垃圾的收纳。', 'https://img.freepik.com/free-photo/biodegradable-trash-bags_23-2148875999.jpg', 345, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (213, '有机水果礼盒', 168, '食品', '精选有机水果，无农药无化肥，新鲜美味，营养丰富，是送礼的绝佳选择。包含苹果、梨、橙子、葡萄等多种水果，采用精美包装，适合各种场合。', 'https://img.freepik.com/free-photo/organic-fruit-gift-box_23-2148876000.jpg', 234, 4.7, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (214, '节能电扇', 299, '家电', '节能电扇，采用直流变频技术，能耗低，风力大，静音设计，为您的夏天带来清凉。有多种风速和模式可选，满足不同使用需求。', 'https://img.freepik.com/free-photo/energy-saving-electric-fan_23-2148876001.jpg', 189, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (215, '天然手工皂', 39, '美妆', '天然手工皂，采用天然成分制成，不含化学添加剂，温和清洁，滋润肌肤，适合各种肤质。有多种香型和功效可选，如滋润、控油、美白等。', 'https://img.freepik.com/free-photo/natural-handmade-soap_23-2148876002.jpg', 267, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (216, '环保餐具', 79.9, '家居用品', '环保餐具，采用竹制或木制材料制成，天然环保，美观实用，是家庭餐桌的理想选择。包含碗、盘、筷子、勺子等多种餐具，适合日常使用。', 'https://img.freepik.com/free-photo/bamboo-wooden-tableware_23-2148876003.jpg', 156, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (217, '有机茶叶', 158, '食品', '有机茶叶，采用有机种植，无农药无化肥，口感醇厚，香气四溢，是品茶爱好者的首选。有多种品种可选，如绿茶、红茶、乌龙茶等，满足不同口味需求。', 'https://img.freepik.com/free-photo/organic-tea-leaves-in-teapot_23-2148876004.jpg', 123, 4.8, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (218, '可降解一次性餐具', 59.9, '家居用品', '可降解一次性餐具，采用玉米淀粉制成，使用后可自然降解，适合户外野餐、聚会等场合使用。包含碗、盘、杯子、叉子、勺子等多种餐具，方便实用。', 'https://img.freepik.com/free-photo/biodegradable-disposable-tableware-for-picnic_23-2148876005.jpg', 312, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (219, '节能电饭煲', 399, '家电', '节能电饭煲，采用智能控制技术，能耗低，煮饭速度快，口感好，为您的家庭节省电费。有多种功能可选，如煮饭、煮粥、煲汤等，满足不同烹饪需求。', 'https://img.freepik.com/free-photo/energy-saving-smart-rice-cooker_23-2148876006.jpg', 178, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (220, '天然棉床上用品', 299, '家居用品', '天然棉床上用品，采用有机棉制成，柔软舒适，透气性好，不含有害化学物质，为您提供健康的睡眠环境。包含床单、被套、枕套等，有多种尺寸和颜色可选。', 'https://img.freepik.com/free-photo/organic-cotton-bedding-set_23-2148876007.jpg', 145, 4.7, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (221, '环保清洁剂', 69.9, '日用品', '环保清洁剂，采用天然成分制成，不含化学添加剂，清洁效果好，对环境友好，适合家庭日常清洁使用。有多种类型可选，如厨房清洁剂、浴室清洁剂、地板清洁剂等。', 'https://img.freepik.com/free-photo/eco-friendly-cleaning-products_23-2148876008.jpg', 289, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (222, '有机咖啡豆', 89, '食品', '有机咖啡豆，采用有机种植，无农药无化肥，口感醇厚，香气浓郁，是咖啡爱好者的首选。有多种烘焙程度可选，如浅烘焙、中烘焙、深烘焙等。', 'https://img.freepik.com/free-photo/organic-coffee-beans_23-2148876009.jpg', 198, 4.7, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (223, '可降解餐盒', 39.9, '家居用品', '可降解餐盒，采用环保材料制成，使用后可自然降解，不会对环境造成污染，适合外卖、野餐等场合使用。密封性好，保温效果佳，方便携带。', 'https://img.freepik.com/free-photo/biodegradable-food-containers_23-2148876010.jpg', 267, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (224, '节能空调', 2999, '家电', '节能空调，采用变频技术，能耗低，制冷效果好，静音设计，为您的夏天带来清凉。有多种匹数可选，适合不同面积的房间使用。', 'https://img.freepik.com/free-photo/energy-saving-air-conditioner_23-2148876011.jpg', 123, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (225, '天然护肤品', 158, '美妆', '天然护肤品，采用天然成分制成，不含化学添加剂，温和护肤，适合各种肤质。有多种类型可选，如面霜、精华液、爽肤水等，满足不同护肤需求。', 'https://img.freepik.com/free-photo/natural-skincare-products_23-2148876012.jpg', 234, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (226, '环保纸巾', 29.9, '日用品', '环保纸巾，采用可回收材料制成，柔软舒适，吸水性强，适合家庭日常使用。不含荧光剂等有害成分，对皮肤友好。', 'https://img.freepik.com/free-photo/eco-friendly-tissue-paper_23-2148876013.jpg', 456, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (227, '有机蜂蜜', 89, '食品', '有机蜂蜜，采用有机养殖，无添加人工糖和防腐剂，口感甜美，营养丰富，适合直接食用或冲饮。有多种花种蜂蜜可选，如槐花蜜、枣花蜜、油菜花蜜等。', 'https://img.freepik.com/free-photo/organic-honey-jar_23-2148876014.jpg', 178, 4.8, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (228, '可降解吸管', 19.9, '日用品', '可降解吸管，采用环保材料制成，使用后可自然降解，不会对环境造成污染，适合各种饮品使用。有多种颜色可选，美观实用。', 'https://img.freepik.com/free-photo/biodegradable-straws_23-2148876015.jpg', 345, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (229, '节能洗衣机', 1999, '家电', '节能洗衣机，采用变频技术，能耗低，洗涤效果好，静音设计，为您的家庭节省电费。有多种洗涤模式可选，适合不同衣物的洗涤需求。', 'https://img.freepik.com/free-photo/energy-saving-washing-machine_23-2148876016.jpg', 145, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (230, '天然彩妆', 129, '美妆', '天然彩妆，采用天然成分制成，不含化学添加剂，温和护肤，适合各种肤质。有多种产品可选，如粉底液、眼影、口红等，满足不同彩妆需求。', 'https://img.freepik.com/free-photo/natural-makeup-products_23-2148876017.jpg', 198, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (231, '环保水杯', 49.9, '日用品', '环保水杯，采用不锈钢或玻璃制成，可重复使用，减少一次性水杯的使用，为环保贡献一份力量。保温效果好，适合日常使用和外出携带。', 'https://img.freepik.com/free-photo/eco-friendly-water-bottle_23-2148876018.jpg', 267, 4.7, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (232, '有机坚果礼盒', 168, '食品', '有机坚果礼盒，采用有机种植，无农药无化肥，营养丰富，口感美味，是送礼的绝佳选择。包含核桃、杏仁、腰果、开心果等多种坚果，采用精美包装。', 'https://img.freepik.com/free-photo/organic-nuts-gift-box_23-2148876019.jpg', 156, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (233, '可降解垃圾袋', 49.9, '家居用品', '可降解垃圾袋，采用环保材料制成，使用后可自然降解，不会对环境造成污染，是家庭垃圾分类的好帮手。韧性强，不易破损，适合各种垃圾的收纳。', 'https://img.freepik.com/free-photo/biodegradable-trash-bags_23-2148875999.jpg', 345, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (234, '节能灯泡', 19.9, '家电', '节能灯泡，采用LED技术，能耗低，使用寿命长，比传统灯泡节能80%以上，为您的家庭节省电费。光线柔和，无频闪，保护眼睛健康。', 'https://img.freepik.com/free-photo/energy-saving-led-light-bulbs_23-2148875990.jpg', 523, 4.7, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (235, '天然香薰蜡烛', 59.9, '家居用品', '天然香薰蜡烛，采用天然大豆蜡制成，不含化学添加剂，燃烧时释放天然香气，营造温馨的居家氛围。有多种香型可选，如薰衣草、玫瑰、柠檬等。', 'https://img.freepik.com/free-photo/natural-aromatherapy-candles_23-2148876020.jpg', 234, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (236, '有机燕麦片', 39.9, '食品', '有机燕麦片，采用有机种植，无农药无化肥，营养丰富，口感美味，适合早餐食用。富含膳食纤维，有助于消化和健康。', 'https://img.freepik.com/free-photo/organic-oatmeal_23-2148876021.jpg', 289, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (237, '可降解餐具', 29.9, '家居用品', '可降解餐具，采用玉米淀粉制成，使用后可自然降解，不会对环境造成污染，适合日常使用。包含叉子、勺子、刀子等，方便实用。', 'https://img.freepik.com/free-photo/biodegradable-cutlery_23-2148876022.jpg', 312, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (238, '节能冰箱', 2999, '家电', '节能冰箱，采用变频技术，能耗低，制冷效果好，静音设计，为您的家庭节省电费。容量大，分区合理，适合家庭日常使用。', 'https://img.freepik.com/free-photo/energy-saving-refrigerator_23-2148876023.jpg', 123, 4.7, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (239, '天然牙膏', 29.9, '美妆', '天然牙膏，采用天然成分制成，不含氟化物等有害成分，温和清洁，保护口腔健康。有多种功效可选，如防蛀、美白、清新口气等。', 'https://img.freepik.com/free-photo/natural-toothpaste_23-2148876024.jpg', 345, 4.5, '2026-04-08 20:03:26');
