INSERT INTO `products` VALUES (283, '有机黑豆', 49.9, '食品', '有机黑豆，采用有机种植，无农药无化肥，营养丰富，口感甜美，适合煮粥、煲汤等。富含蛋白质和膳食纤维，对健康有益。', 'https://img.freepik.com/free-photo/organic-black-beans_23-2148876062.jpg', 198, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (284, '可降解一次性桌布', 29.9, '家居用品', '可降解一次性桌布，采用环保材料制成，使用后可自然降解，不会对环境造成污染，适合家庭聚会、野餐等场合使用。有多种颜色和尺寸可选，美观实用。', 'https://img.freepik.com/free-photo/biodegradable-disposable-tablecloth_23-2148876063.jpg', 234, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (285, '节能电风扇', 299, '家电', '节能电风扇，采用直流变频技术，能耗低，风力大，静音设计，为您的夏天带来清凉。有多种风速和模式可选，满足不同使用需求。', 'https://img.freepik.com/free-photo/energy-saving-electric-fan_23-2148876001.jpg', 145, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (286, '天然护发素', 69.9, '美妆', '天然护发素，采用天然成分制成，不含化学添加剂，温和护发，使头发更加柔顺亮泽。有多种功效可选，如滋润、修复、防脱发等，满足不同护发需求。', 'https://img.freepik.com/free-photo/natural-conditioner_23-2148876064.jpg', 267, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (287, '环保购物车', 129, '日用品', '环保购物车，采用可回收材料制成，结实耐用，可重复使用，减少塑料袋的使用，为环保贡献一份力量。设计时尚美观，容量大，适合日常购物使用。', 'https://img.freepik.com/free-photo/eco-friendly-shopping-cart_23-2148876065.jpg', 178, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (288, '有机绿豆', 39.9, '食品', '有机绿豆，采用有机种植，无农药无化肥，营养丰富，口感甜美，适合煮粥、煲汤等。富含蛋白质和膳食纤维，对健康有益。', 'https://img.freepik.com/free-photo/organic-mung-beans_23-2148876066.jpg', 234, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (289, '可降解一次性杯垫', 19.9, '家居用品', '可降解一次性杯垫，采用环保材料制成，使用后可自然降解，不会对环境造成污染，适合家庭、办公室等场合使用。有多种图案可选，美观实用。', 'https://img.freepik.com/free-photo/biodegradable-coasters_23-2148876067.jpg', 345, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (290, '节能打印机', 999, '家电', '节能打印机，采用低功耗技术，能耗低，打印速度快，为您的家庭或办公室节省电费。有多种功能可选，如打印、复印、扫描等，满足不同使用需求。', 'https://img.freepik.com/free-photo/energy-saving-printer_23-2148876068.jpg', 123, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (291, '天然眼影', 89.9, '美妆', '天然眼影，采用天然成分制成，不含化学添加剂，温和护肤，适合各种肤质。有多种颜色可选，如大地色、粉色、蓝色等，满足不同妆容需求。', 'https://img.freepik.com/free-photo/natural-eyeshadow_23-2148876069.jpg', 198, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (292, '环保笔记本套装', 59.9, '日用品', '环保笔记本套装，采用再生纸制成，不含漂白剂等有害成分，书写流畅，适合日常使用。包含多个不同尺寸的笔记本，满足不同记录需求。', 'https://img.freepik.com/free-photo/eco-friendly-notebooks-set_23-2148876070.jpg', 267, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (293, '有机燕麦', 49.9, '食品', '有机燕麦，采用有机种植，无农药无化肥，营养丰富，口感美味，适合早餐食用。富含膳食纤维，有助于消化和健康。', 'https://img.freepik.com/free-photo/organic-oats_23-2148876071.jpg', 234, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (294, '可降解一次性餐具', 29.9, '家居用品', '可降解一次性餐具，采用玉米淀粉制成，使用后可自然降解，不会对环境造成污染，适合日常使用。包含叉子、勺子、刀子等，方便实用。', 'https://img.freepik.com/free-photo/biodegradable-cutlery_23-2148876022.jpg', 312, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (295, '节能加湿器', 199, '家电', '节能加湿器，采用低功耗技术，能耗低，加湿效果好，为您的家庭提供舒适的湿度环境。有多种容量可选，适合不同面积的房间使用。', 'https://img.freepik.com/free-photo/energy-saving-humidifier_23-2148876072.jpg', 145, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (296, '天然腮红', 69.9, '美妆', '天然腮红，采用天然成分制成，不含化学添加剂，温和护肤，适合各种肤质。有多种颜色可选，如粉色、橘色、红色等，满足不同妆容需求。', 'https://img.freepik.com/free-photo/natural-blush_23-2148876073.jpg', 178, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (297, '环保鼠标垫', 29.9, '日用品', '环保鼠标垫，采用可回收材料制成，结实耐用，可重复使用，减少塑料鼠标垫的使用，为环保贡献一份力量。设计时尚美观，手感舒适，适合办公和游戏使用。', 'https://img.freepik.com/free-photo/eco-friendly-mouse-pad_23-2148876074.jpg', 234, 4.6, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (298, '有机芝麻', 39.9, '食品', '有机芝麻，采用有机种植，无农药无化肥，营养丰富，口感香美，适合烹饪和调味。富含多种营养成分，对健康有益。', 'https://img.freepik.com/free-photo/organic-sesame-seeds_23-2148876075.jpg', 198, 4.5, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (299, '可降解一次性餐纸', 29.9, '家居用品', '可降解一次性餐纸，采用环保材料制成，使用后可自然降解，不会对环境造成污染，适合家庭、餐厅等场合使用。柔软舒适，吸水性强，方便实用。', 'https://img.freepik.com/free-photo/biodegradable-dining-paper_23-2148876076.jpg', 345, 4.4, '2026-04-08 20:03:26');
INSERT INTO `products` VALUES (300, '节能空气净化器', 1299, '家电', '节能空气净化器，采用低功耗技术，能耗低，净化效果好，为您的家庭提供清新的空气环境。有多种功能可选，如除甲醛、除异味、除菌等，满足不同净化需求。', 'https://img.freepik.com/free-photo/energy-saving-air-purifier_23-2148876077.jpg', 123, 4.7, '2026-04-08 20:03:26');
